#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in the log (net zero included), plus SKU-9 from the catalog.
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3 ); seen[$1] = 1 }
     END { for (sku in seen) print sku, net[sku]; print "SKU-9", net["SKU-9"] + 0 }' \
    movements.log | sort > stock.txt

